=== FILE: tb/crc8_block_tb.v ===
`timescale 1ns / 1ps
// Constrained-random, self-checking testbench for crc8_block.
// Reference model written from interface_spec.md (sections 2.1-2.3), not from
// the RTL. Every cycle crc is compared twice: after inputs change (before the
// edge, crc must not move) and after the rising edge (crc must equal the
// model's running value XOR 0xFF). Coverage goals fail the run if the random
// stimulus did not reach the corners the specification names.
module crc8_block_tb;
    // ---------------- knobs (percent per cycle) ----------------
    localparam integer N_RANDOM       = 20000;
    localparam integer P_RST          = 2;   // reset asserted
    localparam integer P_INIT         = 6;   // reload requested
    localparam integer P_VALID        = 70;  // byte offered
    localparam integer P_COINCIDE     = 50;  // valid high when reset/init is high
    localparam integer P_BOUND        = 15;  // byte drawn from 00/FF/80/01
    localparam integer P_BURST_TOGGLE = 1;   // enter/leave long-frame burst mode
    localparam integer P_BURST_VALID  = 95;
    localparam integer LONG_FRAME     = 32;
    localparam integer MAX_REPORTS    = 20;
    localparam integer WATCHDOG_NS    = 2000000;

    reg        clk;
    reg        rst_n;
    reg        init;
    reg        valid;
    reg  [7:0] data;
    wire [7:0] crc;

    crc8_block dut (
        .clk   (clk),
        .rst_n (rst_n),
        .init  (init),
        .valid (valid),
        .data  (data),
        .crc   (crc)
    );

    initial clk = 1'b0;
    always #5 clk = ~clk;

    // ---------------- bookkeeping ----------------
    integer seed;
    integer seed_arg;
    integer passed;
    integer failed;
    integer cyc;
    integer k;
    integer frame_len;
    integer pct;
    reg [31:0] u;
    reg  [7:0] model;
    reg        model_known;
    reg        burst;
    reg        done;
    reg        r_, i_, v_;
    reg  [7:0] d_;
    reg [8*128-1:0] nonce_s;
    reg        nonce_ok;

    // coverage counters
    integer cov_bytes;
    integer cov_init_valid;
    integer cov_rst_valid;
    integer cov_init_mid;
    integer cov_rst_mid;
    integer cov_hold;
    integer cov_long;
    integer cov_b00, cov_bff, cov_b80, cov_b01;
    integer cov_empty;

    // ---------------- reference model (from the specification) ----------------
    // Spec 2.2: for each bit from 7 down to 0, XOR the bit into the top bit of
    // the running value, shift left one place, and if the bit shifted out was
    // 1, XOR with 0x07.
    function [7:0] spec_step(input [7:0] s, input [7:0] d);
        integer b;
        reg [7:0] r;
        reg shifted_out;
        begin
            r = s;
            for (b = 7; b >= 0; b = b - 1) begin
                r[7] = r[7] ^ d[b];
                shifted_out = r[7];
                r = r << 1;
                if (shifted_out)
                    r = r ^ 8'h07;
            end
            spec_step = r;
        end
    endfunction

    // Independent formulation: s' = ((s ^ d) * x^8) mod (x^8 + x^2 + x + 1).
    function [7:0] alt_step(input [7:0] s, input [7:0] d);
        integer b;
        reg [7:0] r;
        begin
            r = s ^ d;
            for (b = 0; b < 8; b = b + 1) begin
                if (r[7])
                    r = (r << 1) ^ 8'h07;
                else
                    r = r << 1;
            end
            alt_step = r;
        end
    endfunction

    // ---------------- random helpers ----------------
    task rnd_raw;
        begin
            u = $random(seed);
        end
    endtask

    task rnd_pct;
        begin
            u = $random(seed);
            pct = u % 100;
        end
    endtask

    // ---------------- checks ----------------
    task check_crc(input integer phase);
        reg [7:0] expv;
        begin
            if (model_known) begin
                expv = model ^ 8'hFF;
                if (crc === expv) begin
                    passed = passed + 1;
                end else begin
                    failed = failed + 1;
                    if (failed <= MAX_REPORTS)
                        $display("crc8_block_tb: MISMATCH cycle %0d phase %0d (0=before edge,1=after edge) t=%0t rst_n=%b init=%b valid=%b data=%h crc=%h expected=%h",
                                 cyc, phase, $time, rst_n, init, valid, data, crc, expv);
                end
            end
        end
    endtask

    // One clock: drive at the falling edge, check before and after the rising edge.
    task drive_cycle(input r, input i, input v, input [7:0] d);
        reg [7:0] nxt;
        reg [7:0] alt;
        begin
            @(negedge clk);
            rst_n = r;
            init  = i;
            valid = v;
            data  = d;
            #1;
            check_crc(0);   // reset is synchronous and crc follows only the running value
            @(posedge clk);
            if (!r) begin
                // CRC-RESET
                if (v) cov_rst_valid = cov_rst_valid + 1;
                if (model_known && frame_len > 0) cov_rst_mid = cov_rst_mid + 1;
                model = 8'hFF;
                model_known = 1'b1;
                frame_len = 0;
            end else if (i) begin
                // CRC-INIT: the reload wins over a byte at the same edge
                if (model_known) begin
                    if (v) cov_init_valid = cov_init_valid + 1;
                    if (frame_len > 0) cov_init_mid = cov_init_mid + 1;
                end
                model = 8'hFF;
                model_known = 1'b1;
                frame_len = 0;
            end else if (v) begin
                // CRC-POLY / CRC-ORDER
                if (model_known) begin
                    nxt = spec_step(model, d);
                    alt = alt_step(model, d);
                    if (nxt !== alt) begin
                        failed = failed + 1;
                        $display("crc8_block_tb: MODEL DISAGREEMENT state=%h data=%h spec=%h alt=%h", model, d, nxt, alt);
                    end
                    model = nxt;
                    frame_len = frame_len + 1;
                    cov_bytes = cov_bytes + 1;
                    if (frame_len == LONG_FRAME) cov_long = cov_long + 1;
                    if (d == 8'h00) cov_b00 = cov_b00 + 1;
                    if (d == 8'hFF) cov_bff = cov_bff + 1;
                    if (d == 8'h80) cov_b80 = cov_b80 + 1;
                    if (d == 8'h01) cov_b01 = cov_b01 + 1;
                end
            end else begin
                // CRC-HOLD
                if (model_known) cov_hold = cov_hold + 1;
            end
            #1;
            check_crc(1);   // CRC-FINAL
            if (model_known && (!r || i)) begin
                // CRC-EMPTY: literal value from the specification
                cov_empty = cov_empty + 1;
                if (crc === 8'h00) begin
                    passed = passed + 1;
                end else begin
                    failed = failed + 1;
                    if (failed <= MAX_REPORTS)
                        $display("crc8_block_tb: EMPTY CHECK cycle %0d t=%0t rst_n=%b init=%b valid=%b data=%h crc=%h expected=00",
                                 cyc, $time, r, i, v, d, crc);
                end
            end
            cyc = cyc + 1;
        end
    endtask

    task goal(input integer id, input integer have, input integer need);
        begin
            if (have >= need) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $display("crc8_block_tb: COVERAGE HOLE goal %0d reached %0d, need %0d", id, have, need);
            end
        end
    endtask

    task finish_run;
        integer j;
        reg [7:0] ch;
        begin
            if (!nonce_ok) begin
                failed = failed + 1;
                $display("crc8_block_tb: no nonce plusarg found");
            end
            $write("NIRMAAN-SIM ");
            if (nonce_ok) begin
                for (j = 127; j >= 0; j = j - 1) begin
                    ch = nonce_s[j*8 +: 8];
                    if (ch != 8'h00)
                        $write("%c", ch);
                end
            end else begin
                $write("NO-NONCE");
            end
            $display(" %0d passed, %0d failed", passed, failed);
            $finish;
        end
    endtask

    // ---------------- main sequence ----------------
    initial begin
        passed = 0; failed = 0; cyc = 0; frame_len = 0;
        model = 8'h00; model_known = 1'b0; burst = 1'b0; done = 1'b0;
        cov_bytes = 0; cov_init_valid = 0; cov_rst_valid = 0; cov_init_mid = 0;
        cov_rst_mid = 0; cov_hold = 0; cov_long = 0;
        cov_b00 = 0; cov_bff = 0; cov_b80 = 0; cov_b01 = 0; cov_empty = 0;

        nonce_s = 0;
        nonce_ok = 1'b0;
        if ($value$plusargs("NIRMAAN_NONCE=%s", nonce_s)) nonce_ok = 1'b1;
        else if ($value$plusargs("nirmaan_nonce=%s", nonce_s)) nonce_ok = 1'b1;
        else if ($value$plusargs("NONCE=%s", nonce_s)) nonce_ok = 1'b1;
        else if ($value$plusargs("nonce=%s", nonce_s)) nonce_ok = 1'b1;

        seed = 32'h0C8C0007;
        if ($value$plusargs("seed=%d", seed_arg)) seed = seed_arg;
        $display("crc8_block_tb: seed=%0d random_cycles=%0d", seed, N_RANDOM);

        rst_n = 1'b0; init = 1'b0; valid = 1'b0; data = 8'h00;

        // Directed prologue
        drive_cycle(1'b0, 1'b0, 1'b0, 8'h00);  // reset
        drive_cycle(1'b0, 1'b0, 1'b1, 8'hA5);  // reset with a byte offered
        drive_cycle(1'b1, 1'b0, 1'b0, 8'h3C);  // hold right after reset: crc stays 00
        drive_cycle(1'b1, 1'b0, 1'b1, 8'h00);
        drive_cycle(1'b1, 1'b0, 1'b1, 8'hFF);
        drive_cycle(1'b1, 1'b0, 1'b1, 8'h80);
        drive_cycle(1'b1, 1'b0, 1'b1, 8'h01);
        drive_cycle(1'b1, 1'b0, 1'b0, 8'h5A);  // hold mid-frame with data changing
        drive_cycle(1'b1, 1'b1, 1'b1, 8'hC3);  // init wins over the byte
        drive_cycle(1'b1, 1'b0, 1'b1, 8'h12);
        drive_cycle(1'b1, 1'b0, 1'b1, 8'h34);
        drive_cycle(1'b0, 1'b1, 1'b1, 8'h56);  // reset mid-frame with init and a byte

        // Constrained-random phase
        for (k = 0; k < N_RANDOM; k = k + 1) begin
            rnd_pct;
            if (pct < P_BURST_TOGGLE) burst = ~burst;

            rnd_pct;
            r_ = burst ? 1'b1 : (pct >= P_RST);
            rnd_pct;
            i_ = burst ? 1'b0 : (pct < P_INIT);
            rnd_pct;
            if (!r_ || i_)
                v_ = (pct < P_COINCIDE);
            else
                v_ = (pct < (burst ? P_BURST_VALID : P_VALID));

            rnd_pct;
            if (pct < P_BOUND) begin
                rnd_raw;
                case (u[9:8])
                    2'd0: d_ = 8'h00;
                    2'd1: d_ = 8'hFF;
                    2'd2: d_ = 8'h80;
                    default: d_ = 8'h01;
                endcase
            end else begin
                rnd_raw;
                d_ = u[19:12];
            end

            drive_cycle(r_, i_, v_, d_);
        end

        // Coverage goals
        $display("crc8_block_tb: coverage bytes=%0d init_valid=%0d rst_valid=%0d init_mid=%0d rst_mid=%0d hold=%0d long=%0d b00=%0d bFF=%0d b80=%0d b01=%0d empty=%0d",
                 cov_bytes, cov_init_valid, cov_rst_valid, cov_init_mid, cov_rst_mid,
                 cov_hold, cov_long, cov_b00, cov_bff, cov_b80, cov_b01, cov_empty);
        goal(1,  cov_bytes,      5000);
        goal(2,  cov_init_valid, 50);
        goal(3,  cov_rst_valid,  20);
        goal(4,  cov_init_mid,   50);
        goal(5,  cov_rst_mid,    20);
        goal(6,  cov_hold,       1000);
        goal(7,  cov_long,       5);
        goal(8,  cov_b00,        20);
        goal(9,  cov_bff,        20);
        goal(10, cov_b80,        20);
        goal(11, cov_b01,        20);
        goal(12, cov_empty,      100);

        done = 1'b1;
        finish_run;
    end

    // Watchdog
    initial begin
        #(WATCHDOG_NS);
        if (!done) begin
            failed = failed + 1;
            $display("crc8_block_tb: WATCHDOG timeout at cycle %0d", cyc);
            done = 1'b1;
            finish_run;
        end
    end
endmodule
=== END FILE ===
